mapper.select:
select t.PLAYER_NAME,t.PLAYER_NUMBER,t.PHOTO,

    ${param.fields}
    s.*
 from dream_player t right join
    (select * from player_stats where SEASON_NUM = #{param.seasonNum} ) s  on t.PLAYER_ID = s.PLAYER_ID




    and s.PLAYER_POSITION like CONCAT('%',#{param.playerPosition},'%')



    and SUBSTRING_INDEX(s.PLAYER_TEAM, '->', -1) = #{param.playerTeam}




        order by ${param.field}


        order by s.PLAYER_AVG_SCORE desc

select t.PLAYER_NAME,t.PLAYER_NUMBER,t.PLAYER_BIRTHDAY,s.* from dream_player t right join (select * from player_stats ) s on t.PLAYER_ID = s.PLAYER_ID
order by ${param.field}
order by (s.SEASON_NUM = 99), s.SEASON_NUM desc

select t.PLAYER_NAME,t.PLAYER_NUMBER,

    ${param.fields}
    s.*
 from dream_player t right join
    (select * from player_playoff_stats where SEASON_NUM = #{param.seasonNum} ) s  on t.PLAYER_ID = s.PLAYER_ID




    and s.PLAYER_POSITION like CONCAT('%',#{param.playerPosition},'%')



    and SUBSTRING_INDEX(s.PLAYER_TEAM, '->', -1) = #{param.playerTeam}




        order by ${param.field}


        order by s.PLAYER_AVG_SCORE desc

select t.PLAYER_NAME, t.PLAYER_NUMBER, t.PHOTO, s.* from dream_player t right join (select * from player_playoff_round_stats where SEASON_NUM = #{param.seasonNum} and `ROUND` = #{param.round}) s on t.PLAYER_ID = s.PLAYER_ID
and s.PLAYER_TEAM = #{param.playerTeam}
order by ${param.field}
order by s.PLAYER_AVG_SCORE desc

select SEASON_NUM as seasonNum, SEASON_TYPE as seasonType, count(*) as games
from player_game_stats where PLAYER_ID = #{playerId}
group by SEASON_NUM, SEASON_TYPE order by SEASON_NUM desc, SEASON_TYPE

select c.BR_ID as brId, c.PLAYER_ID as playerId,
coalesce(p.PLAYER_NAME, c.PLAYER_NAME_ZH, c.PLAYER_NAME) as playerName, c.PLAYER_NAME as nameEn, c.FIRST_YEAR as firstYear, c.LAST_YEAR as lastYear, c.SEASONS as seasons, ${expr} as val, rank() over (order by ${expr} desc) as rk from nba_career_totals c left join dream_player p on p.PLAYER_ID = c.PLAYER_ID where ${expr} > 0 order by ${expr} desc
limit #{limit}

mapper.sql:
1=1
and (t.PLAYER_NAME like CONCAT('%', #{param.playerName}, '%') or t.NAME_EN like CONCAT('%', #{param.playerName}, '%'))
and t.PLAYER_ID = #{param.playerId}
